function pascalCase(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// build a plain-JS sample value map for a field list
function buildSample(fields, seed = 1) {
  const sample = {};
  for (const f of fields) {
    sample[f.name] = sampleValueFor(f, seed);
  }
  return sample;
}

function sampleValueFor(f, seed) {
  if (f.kind === 'Embedded') {
    const obj = {};
    for (const sf of f.fields) obj[sf.name] = sampleValueFor(sf, seed);
    return obj;
  }
  if (f.kind === 'Int') return 100 + seed;
  if (f.kind === 'Float') return 12.5;
  if (f.kind === 'Boolean') return f.hasDefault ? f.default : true;
  if (f.kind === 'Date') return '__DATE__';
  if (f.email) return `user${seed}@example.com`;
  if (f.name === 'street') return '123 Main St';
  if (f.name === 'city') return 'Springfield';
  if (f.name === 'country') return 'Wonderland';
  if (f.name === 'zipCode') return '12345';
  return `${f.name}-${seed}`;
}

function renderJsValue(v) {
  if (v === '__DATE__') return `new Date('2024-01-01T00:00:00.000Z')`;
  if (typeof v === 'object' && v !== null) {
    const entries = Object.entries(v).map(([k, val]) => `${k}: ${renderJsValue(val)}`);
    return `{ ${entries.join(', ')} }`;
  }
  return JSON.stringify(v);
}

function renderSampleObject(sample, fields) {
  const lines = fields.map((f) => `    ${f.name}: ${renderJsValue(sample[f.name])},`);
  return `{\n${lines.join('\n')}\n  }`;
}

// GraphQL variable literal renderer (for e2e / bruno) — dates as ISO strings
function renderGqlValue(v) {
  if (v === '__DATE__') return `'2024-01-01T00:00:00.000Z'`;
  if (typeof v === 'object' && v !== null) {
    const entries = Object.entries(v).map(([k, val]) => `${k}: ${renderGqlValue(val)}`);
    return `{ ${entries.join(', ')} }`;
  }
  return JSON.stringify(v);
}

function renderJsonValue(v, indent = '') {
  if (v === '__DATE__') return `"2024-01-01T00:00:00.000Z"`;
  if (typeof v === 'object' && v !== null) {
    const inner = indent + '  ';
    const entries = Object.entries(v).map(([k, val]) => `${inner}"${k}": ${renderJsonValue(val, inner)}`);
    return `{\n${entries.join(',\n')}\n${indent}}`;
  }
  return JSON.stringify(v);
}

function generateE2e(cfg) {
  const { name, plural, dir, fields } = cfg;
  const camel = pascalToCamel(name);
  const sample = buildSample(fields, 1);
  const uniqueFields = fields.filter((f) => f.unique);
  const keyField = uniqueFields[0];
  const updatableField =
    fields.find((f) => !f.unique && f.kind === 'String') || fields.find((f) => !f.unique && f.kind !== 'Embedded');
  const newValue = updatableField.kind === 'String' ? `'${sample[updatableField.name]}-updated'` : JSON.stringify(sample[updatableField.name] + 1);

  const selectFields = fields.map((f) => (f.kind === 'Embedded' ? `${f.name} { ${f.fields.map((sf) => sf.name).join(' ')} }` : f.name)).join(' ');
  const keySelect = keyField.name;

  const content = `import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { App } from 'supertest/types';
import { Connection } from 'mongoose';
import { getConnectionToken } from '@nestjs/mongoose';
import { AppModule } from './../src/app.module';

interface GqlResponse {
  data?: Record<string, any>;
  errors?: Array<{ message: string }>;
}

// Requires MongoDB running (docker compose up -d mongodb) — AppModule boots
// the real database connection.
describe('${pascalCase(plural)} (e2e)', () => {
  let app: INestApplication<App>;
  let connection: Connection;

  const create${name} = ${renderJsE2eObject(sample, fields)};

  const gql = async (
    query: string,
    variables?: Record<string, unknown>,
  ): Promise<GqlResponse> => {
    const res = await request(app.getHttpServer())
      .post('/graphql')
      .send({ query, variables })
      .expect(200);
    return res.body as GqlResponse;
  };

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    // Mirror the global pipe from main.ts — whitelist behavior is part of the
    // contract under test.
    app.useGlobalPipes(
      new ValidationPipe({ whitelist: true, transform: true }),
    );
    await app.init();

    connection = app.get<Connection>(getConnectionToken());
    await connection.collection('${plural}').deleteMany({});
  });

  afterAll(async () => {
    await connection.collection('${plural}').deleteMany({});
    await app.close();
  });

  it('create${name} persists and returns the ${camel}', async () => {
    const body = await gql(
      \`mutation($input: Create${name}Input!) {
        create${name}(create${name}: $input) { ${selectFields} }
      }\`,
      { input: create${name} },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.create${name}).toEqual(create${name});
  });

  it('${plural} lists the created ${camel}', async () => {
    const body = await gql(\`{ ${plural} { ${keySelect} } }\`);

    expect(body.errors).toBeUndefined();
    expect(body.data?.${plural}).toEqual([{ ${keySelect}: create${name}.${keySelect} }]);
  });

  it('${camel} finds by ${keySelect}', async () => {
    const body = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.${camel}).toEqual({
      ${keySelect}: create${name}.${keySelect},
    });
  });

  it('update${name} applies and persists the change', async () => {
    const newValue = ${newValue};

    const updated = await gql(
      \`mutation($args: Update${name}Args!) {
        update${name}(update${name}Args: $args) { ${keySelect} ${updatableField.name} }
      }\`,
      {
        args: {
          query: { ${keySelect}: create${name}.${keySelect} },
          payload: { ${updatableField.name}: newValue },
        },
      },
    );

    expect(updated.errors).toBeUndefined();
    expect(updated.data?.update${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
      ${updatableField.name}: newValue,
    });

    const persisted = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${updatableField.name} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(persisted.data?.${camel}).toEqual({ ${updatableField.name}: newValue });
  });

  it('remove${name} deletes the ${camel}', async () => {
    const removed = await gql(
      \`mutation($get: Get${name}Input!) {
        remove${name}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(removed.errors).toBeUndefined();
    expect(removed.data?.remove${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
    });

    const list = await gql(\`{ ${plural} { ${keySelect} } }\`);
    expect(list.data?.${plural}).toEqual([]);
  });
});
`;
  fs.writeFileSync(path.join(ROOT, 'test', `${dir}.e2e-spec.ts`), content);
}

function renderJsE2eObject(sample, fields) {
  const lines = fields.map((f) => `    ${f.name}: ${renderJsValue(sample[f.name])},`);
  return `{\n${lines.join('\n')}\n  }`;
}

