    ]),
  ],
})
export class ${moduleClass} {}
`;
    fs.writeFileSync(path.join(dirPath, `${dir}.module.ts`), content);
  }

  // ---- service.spec.ts ----
  {
    const sample = buildSample(fields);
    const keyField = uniqueFields[0];
    const keyQuery = `{ ${keyField.name}: ${JSON.stringify(sample[keyField.name])} }`;
    const updatableField = fields.find((f) => !f.unique && f.kind === 'String' && f.name !== keyField.name) ||
      fields.find((f) => !f.unique && f.kind !== 'Embedded');
    const newValue = updatableField.kind === 'String' ? `'${sample[updatableField.name]}-updated'` : JSON.stringify(sample[updatableField.name]);

    const content = `import { Test, TestingModule } from '@nestjs/testing';
