'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = '/workspace';

// ---------- field helpers ----------

function scalarField(name, kind, opts = {}) {
  return {
    name,
    kind, // String | Int | Float | Boolean | Date
    required: opts.required !== false,
    unique: !!opts.unique,
    hasDefault: Object.prototype.hasOwnProperty.call(opts, 'default'),
    default: opts.default,
    optional: !!opts.optional,
    email: !!opts.email,
  };
}

function embeddedField(name, typeName, fields) {
  return {
    name,
    kind: 'Embedded',
    typeName,
    required: true,
    unique: false,
    hasDefault: false,
    optional: false,
    fields,
  };
}

const createOptional = (f) => f.hasDefault || f.optional;
const entityNullable = (f) => f.optional;

const gqlTypeExpr = (f) => {
  if (f.kind === 'Embedded') return f.typeName;
  if (f.kind === 'Int') return 'Int';
  if (f.kind === 'Float') return 'Float';
  if (f.kind === 'Date') return 'Date';
  if (f.kind === 'Boolean') return 'Boolean';
  return 'String';
};

const inputTypeExpr = (f) => (f.kind === 'Embedded' ? `${f.typeName}Input` : gqlTypeExpr(f));

const tsTypeExpr = (f) => {
  if (f.kind === 'Embedded') return f.typeName;
  if (f.kind === 'Int' || f.kind === 'Float') return 'number';
  if (f.kind === 'Date') return 'Date';
  if (f.kind === 'Boolean') return 'boolean';
  return 'string';
};

const inputTsTypeExpr = (f) => (f.kind === 'Embedded' ? `${f.typeName}Input` : tsTypeExpr(f));

const validatorDecorator = (f) => {
  if (f.kind === 'Embedded') return null; // uses ValidateNested
  if (f.kind === 'Int') return 'IsInt';
  if (f.kind === 'Float') return 'IsNumber';
  if (f.kind === 'Date') return 'IsDate';
  if (f.kind === 'Boolean') return 'IsBoolean';
  return f.email ? 'IsEmail' : 'IsString';
};

// ---------- code renderers ----------

function renderImports(imports) {
  // imports: array of {from, names: []}
  return imports
    .filter((i) => i.names.length > 0)
    .map((i) => `import { ${[...new Set(i.names)].sort().join(', ')} } from '${i.from}';`)
    .join('\n');
}

function renderFieldBlockEntity(f) {
  const gqlType = gqlTypeExpr(f);
  const nullable = entityNullable(f);
  const opts = nullable ? `, { nullable: true }` : '';
  const bang = nullable ? '?' : '!';
  const lines = [`  @Field(() => ${gqlType}${opts})`];
  if (f.kind === 'Embedded') {
    lines.push(`  @ValidateNested()`, `  @Type(() => ${f.typeName})`);
  } else {
    if (nullable) lines.push('  @IsOptional()');
    lines.push(`  @${validatorDecorator(f)}()`);
  }
  lines.push(`  ${f.name}${bang}: ${tsTypeExpr(f)};`);
  return lines.join('\n');
}

function renderFieldBlockCreate(f) {
  const gqlType = inputTypeExpr(f);
  const nullable = createOptional(f);
  const opts = nullable ? `, { nullable: true }` : '';
  const bang = nullable ? '?' : '!';
  const lines = [`  @Field(() => ${gqlType}${opts})`];
  if (f.kind === 'Embedded') {
    if (nullable) lines.push('  @IsOptional()');
    lines.push(`  @ValidateNested()`, `  @Type(() => ${f.typeName}Input)`);
  } else {
    if (nullable) lines.push('  @IsOptional()');
    lines.push(`  @${validatorDecorator(f)}()`);
  }
  lines.push(`  ${f.name}${bang}: ${inputTsTypeExpr(f)};`);
  return lines.join('\n');
}

function renderFieldBlockUpdate(f) {
  // all fields optional
  const gqlType = inputTypeExpr(f);
  const lines = [`  @Field(() => ${gqlType}, { nullable: true })`, '  @IsOptional()'];
  if (f.kind === 'Embedded') {
    lines.push(`  @ValidateNested()`, `  @Type(() => ${f.typeName}Input)`);
  } else {
    lines.push(`  @${validatorDecorator(f)}()`);
  }
  lines.push(`  ${f.name}?: ${inputTsTypeExpr(f)};`);
  return lines.join('\n');
}

function renderFieldBlockGet(f) {
  const gqlType = gqlTypeExpr(f);
  const lines = [
    `  @Field(() => ${gqlType}, { nullable: true })`,
    '  @IsOptional()',
    `  @${validatorDecorator(f)}()`,
    `  ${f.name}?: ${tsTypeExpr(f)};`,
  ];
  return lines.join('\n');
}

function collectValidatorNames(fields, mode) {
  const names = new Set();
  let needsType = false;
  for (const f of fields) {
    if (f.kind === 'Embedded') {
      needsType = true;
      names.add('ValidateNested');
      if (mode === 'create' && createOptional(f)) names.add('IsOptional');
      if (mode === 'update') names.add('IsOptional');
      continue;
    }
    const v = validatorDecorator(f);
    names.add(v);
    if (mode === 'entity' && entityNullable(f)) names.add('IsOptional');
    if (mode === 'create' && createOptional(f)) names.add('IsOptional');
    if (mode === 'update') names.add('IsOptional');
    if (mode === 'get') names.add('IsOptional');
  }
  return { names: [...names], needsType };
}

function collectGqlNames(fields) {
  const names = new Set();
  for (const f of fields) {
    const t = gqlTypeExpr(f);
    if (t === 'Int' || t === 'Float') names.add(t);
  }
  return [...names];
}

// ---------- embedded type files ----------

function embeddedTypeName(typeName) {
  return typeName;
}

function renderEmbeddedEntity(dirPath, embedded) {
  const gqlExtra = collectGqlNames(embedded.fields);
  const { names: validatorNames } = collectValidatorNames(embedded.fields, 'entity');
  const body = embedded.fields.map(renderFieldBlockEntity).join('\n\n');
  const content = `${renderImports([
    { from: '@nestjs/graphql', names: ['Field', 'ObjectType', ...gqlExtra] },
    { from: 'class-validator', names: validatorNames },
  ])}

@ObjectType()
export class ${embedded.typeName} {
${body}
}
`;
  fs.writeFileSync(path.join(dirPath, 'entities', `${kebab(embedded.typeName)}.entity.ts`), content);
}

function renderEmbeddedInput(dirPath, embedded) {
  const gqlExtra = collectGqlNames(embedded.fields);
  const { names: validatorNames } = collectValidatorNames(embedded.fields, 'entity');
  const body = embedded.fields.map(renderFieldBlockEntity).join('\n\n');
  // input uses same required-ness as entity (embedded sub-fields all required per spec)
  const content = `${renderImports([
    { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
    { from: 'class-validator', names: validatorNames },
  ])}

@InputType()
export class ${embedded.typeName}Input {
${body}
}
`;
  fs.writeFileSync(path.join(dirPath, 'dto', `${kebab(embedded.typeName)}.input.dto.ts`), content);
}

// ---------- utils ----------

function kebab(str) {
  return str
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .toLowerCase();
}

function pascalToCamel(str) {
  return str.charAt(0).toLowerCase() + str.slice(1);
}

// ---------- main per-entity generation ----------

function generateEntity(cfg) {
  const { name, plural, dir, fields } = cfg;
  const camel = pascalToCamel(name);
  const dirPath = path.join(ROOT, 'src', dir);
  const testDirs = ['dto', 'entities', 'schemas'].map((d) => path.join(dirPath, d));
  for (const d of [dirPath, ...testDirs]) fs.mkdirSync(d, { recursive: true });

  const embeddedFields = fields.filter((f) => f.kind === 'Embedded');
  for (const ef of embeddedFields) {
    renderEmbeddedEntity(dirPath, ef);
    renderEmbeddedInput(dirPath, ef);
  }

  const uniqueFields = fields.filter((f) => f.unique);

  // ---- entity.ts ----
  {
    const gqlExtra = collectGqlNames(fields);
    const { names: validatorNames, needsType } = collectValidatorNames(fields, 'entity');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'ObjectType', ...gqlExtra] },
    ];
    if (needsType) imports.push({ from: 'class-transformer', names: ['Type'] });
    imports.push({ from: 'class-validator', names: validatorNames });
    for (const ef of embeddedFields) {
      imports.push({ from: `./${kebab(ef.typeName)}.entity`, names: [ef.typeName] });
    }
    const body = fields.map(renderFieldBlockEntity).join('\n\n');
    const content = `${renderImports(imports)}

@ObjectType()
export class ${name} {
${body}
}
`;
    fs.writeFileSync(path.join(dirPath, 'entities', `${kebab(name)}.entity.ts`), content);
  }

  // ---- dto/create-<x>.input.dto.ts ----
  {
    const gqlExtra = collectGqlNames(fields);
    const { names: validatorNames, needsType } = collectValidatorNames(fields, 'create');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
    ];
    if (needsType) imports.push({ from: 'class-transformer', names: ['Type'] });
    imports.push({ from: 'class-validator', names: validatorNames });
    for (const ef of embeddedFields) {
      imports.push({ from: `../dto/${kebab(ef.typeName)}.input.dto`, names: [`${ef.typeName}Input`] });
    }
    const body = fields.map(renderFieldBlockCreate).join('\n\n');
    const content = `${renderImports(imports)}

@InputType()
export class Create${name}Input {
${body}
}
`;
    fs.writeFileSync(path.join(dirPath, 'dto', `create-${kebab(name)}.input.dto.ts`), content);
  }

  // ---- dto/get-<x>.input.dto.ts ----
  {
    const gqlExtra = collectGqlNames(uniqueFields);
    const { names: validatorNames } = collectValidatorNames(uniqueFields, 'get');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
      { from: 'class-validator', names: validatorNames },
    ];
    const body = uniqueFields.map(renderFieldBlockGet).join('\n\n');
    const content = `${renderImports(imports)}

@InputType()
export class Get${name}Input {
${body}
}
`;
    fs.writeFileSync(path.join(dirPath, 'dto', `get-${kebab(name)}.input.dto.ts`), content);
  }

  // ---- dto/update-<x>.input.dto.ts ----
  {
    const gqlExtra = collectGqlNames(fields);
    const { names: validatorNames } = collectValidatorNames(fields, 'update');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
      { from: 'class-transformer', names: ['Type'] },
      { from: 'class-validator', names: [...new Set([...validatorNames, 'ValidateNested'])] },
      { from: `./get-${kebab(name)}.input.dto`, names: [`Get${name}Input`] },
    ];
    for (const ef of embeddedFields) {
      imports.push({ from: `../dto/${kebab(ef.typeName)}.input.dto`, names: [`${ef.typeName}Input`] });
    }
    const body = fields.map(renderFieldBlockUpdate).join('\n\n');
    const content = `${renderImports(imports)}

@InputType()
export class Update${name}Payload {
${body}
}

@InputType()
export class Update${name}Args {
  @Field(() => Get${name}Input)
  @ValidateNested()
  @Type(() => Get${name}Input)
  query!: Get${name}Input;

  @Field(() => Update${name}Payload)
  @ValidateNested()
  @Type(() => Update${name}Payload)
  payload!: Update${name}Payload;
}
`;
    fs.writeFileSync(path.join(dirPath, 'dto', `update-${kebab(name)}.input.dto.ts`), content);
  }

  // ---- schemas/<x>.schema.ts ----
  {
    const schemaFieldLine = (f, indent = '  ') => {
      if (f.kind === 'Embedded') {
        return `${indent}${f.name}: { type: ${f.typeName}Schema, required: true },`;
      }
      const mongoType =
        f.kind === 'Int' || f.kind === 'Float'
          ? 'Number'
          : f.kind === 'Date'
            ? 'Date'
            : f.kind === 'Boolean'
              ? 'Boolean'
              : 'String';
      const parts = [`type: ${mongoType}`, `required: ${f.required && !f.optional}`];
      if (f.unique) parts.push('unique: true');
      if (f.hasDefault) parts.push(`default: ${JSON.stringify(f.default)}`);
      return `${indent}${f.name}: { ${parts.join(', ')} },`;
    };

    const embeddedSchemas = embeddedFields
      .map((ef) => {
        const subLines = ef.fields.map((sf) => schemaFieldLine(sf, '    '));
        return `const ${ef.typeName}Schema = new mongoose.Schema(
  {
${subLines.join('\n')}
  },
  { _id: false },
);
`;
      })
      .join('\n');

    const mainLines = fields.map((f) => schemaFieldLine(f));

    const content = `import * as mongoose from 'mongoose';

${embeddedSchemas}export const ${name}Schema = new mongoose.Schema({}, { versionKey: false });

${name}Schema.add({
${mainLines.join('\n')}
});
`;
    fs.writeFileSync(path.join(dirPath, 'schemas', `${kebab(name)}.schema.ts`), content);
  }

  // ---- repository ----
  {
    const content = `import { Injectable } from '@nestjs/common';
import { InjectConnection, InjectModel } from '@nestjs/mongoose';
import { Connection, Model } from 'mongoose';
import { AbstractRepository } from '@app/common';
import { ${name} } from './entities/${kebab(name)}.entity';

@Injectable()
export class ${name}Repository extends AbstractRepository<${name}> {
  constructor(
    @InjectModel(${name}.name) private readonly ${camel}Model: Model<${name}>,
    @InjectConnection() connection: Connection,
  ) {
    super(${camel}Model, connection);
  }
}
`;
    fs.writeFileSync(path.join(dirPath, `${kebab(name)}.repository.ts`), content);
  }

  // ---- service ----
  {
    const content = `import { Injectable } from '@nestjs/common';
import { ${name}Repository } from './${kebab(name)}.repository';
import { ${name} } from './entities/${kebab(name)}.entity';
import { Create${name}Input } from './dto/create-${kebab(name)}.input.dto';
import { Get${name}Input } from './dto/get-${kebab(name)}.input.dto';
import {
  Update${name}Args,
  Update${name}Payload,
} from './dto/update-${kebab(name)}.input.dto';

@Injectable()
export class ${name}Service {
  constructor(private readonly repo: ${name}Repository) {}

  async create(create${name}: Create${name}Input): Promise<${name}> {
    return await this.repo.create<Create${name}Input, ${name}>(create${name});
  }

  async findAll(): Promise<${name}[]> {
    return await this.repo.findMany<${name}>({});
  }

  async findOne(get${name}: Get${name}Input): Promise<${name} | null> {
    return await this.repo.findOne<${name}>(get${name});
  }

  async update({ query, payload }: Update${name}Args): Promise<${name} | null> {
    return await this.repo.update<Update${name}Payload, ${name}>(query, payload, {
      upsert: false,
    });
  }

  async remove(remove${name}: Get${name}Input): Promise<${name} | null> {
    return await this.repo.remove<${name}>(remove${name});
  }
}
`;
    fs.writeFileSync(path.join(dirPath, `${kebab(name)}.service.ts`), content);
  }

  // ---- resolver ----
  {
    const content = `import { Args, Mutation, Query, Resolver } from '@nestjs/graphql';
import { TryAndCatch } from '@app/common';
import { ${name}Service } from './${kebab(name)}.service';
import { ${name} } from './entities/${kebab(name)}.entity';
import { Create${name}Input } from './dto/create-${kebab(name)}.input.dto';
import { Get${name}Input } from './dto/get-${kebab(name)}.input.dto';
import { Update${name}Args } from './dto/update-${kebab(name)}.input.dto';

@Resolver(() => ${name})
export class ${name}Resolver {
  constructor(private readonly ${camel}Service: ${name}Service) {}

  @Mutation(() => ${name}, { name: 'create${name}' })
  @TryAndCatch()
  create(@Args('create${name}') create${name}: Create${name}Input) {
    return this.${camel}Service.create(create${name});
  }

  @Query(() => [${name}], {
    name: '${plural}',
    description: 'returns list of ${name}',
  })
  @TryAndCatch()
  findAll() {
    return this.${camel}Service.findAll();
  }

  @Query(() => ${name}, {
    name: '${camel}',
    description: 'gets ${name} either by keys',
  })
  @TryAndCatch()
  findOne(
    @Args('get${name}', { type: () => Get${name}Input })
    get${name}: Get${name}Input,
  ) {
    return this.${camel}Service.findOne(get${name});
  }

  @Mutation(() => ${name}, { name: 'update${name}' })
  @TryAndCatch()
  update(@Args('update${name}Args') update${name}: Update${name}Args) {
    return this.${camel}Service.update(update${name});
  }

  @Mutation(() => ${name}, { name: 'remove${name}' })
  @TryAndCatch()
  remove(
    @Args('get${name}', { type: () => Get${name}Input })
    get${name}: Get${name}Input,
  ) {
    return this.${camel}Service.remove(get${name});
  }
}
`;
    fs.writeFileSync(path.join(dirPath, `${kebab(name)}.resolver.ts`), content);
  }

  // ---- module ----
  {
    const moduleClass = `${pascalCase(plural)}Module`;
    const content = `import { Module } from '@nestjs/common';
import { DatabaseModule } from '@app/common';
import { MongooseModule } from '@nestjs/mongoose';
import { ${name}Resolver } from './${kebab(name)}.resolver';
import { ${name}Service } from './${kebab(name)}.service';
import { ${name} } from './entities/${kebab(name)}.entity';
import { ${name}Schema } from './schemas/${kebab(name)}.schema';
import { ${name}Repository } from './${kebab(name)}.repository';

@Module({
  providers: [${name}Resolver, ${name}Service, ${name}Repository],
  imports: [
    DatabaseModule,
    MongooseModule.forFeature([
      {
        name: ${name}.name,
        schema: ${name}Schema,
        collection: '${plural}',
      },
    ]),
  ],
})
export class ${moduleClass} {}
`;
    fs.writeFileSync(path.join(dirPath, `${dir}.module.ts`), content);
  }

  // ---- service.spec.ts ----
  {
    const sample = buildSample(fields);
    const keyField = uniqueFields[0];
    const keyQuery = `{ ${keyField.name}: ${JSON.stringify(sample[keyField.name])} }`;
    const updatableField = fields.find((f) => !f.unique && f.kind === 'String' && f.name !== keyField.name) ||
      fields.find((f) => !f.unique && f.kind !== 'Embedded');
    const newValue = renderUpdatedJsValue(updatableField, sample[updatableField.name]);

    const content = `import { Test, TestingModule } from '@nestjs/testing';
import { ${name}Service } from './${kebab(name)}.service';
import { ${name}Repository } from './${kebab(name)}.repository';
import { ${name} } from './entities/${kebab(name)}.entity';

describe('${name}Service', () => {
  let service: ${name}Service;

  const repo = {
    create: jest.fn(),
    findMany: jest.fn(),
    findOne: jest.fn(),
    update: jest.fn(),
    remove: jest.fn(),
  };

  const sample: ${name} = ${renderSampleObject(sample, fields)};

  const keyQuery = ${keyQuery};

  beforeEach(async () => {
    jest.clearAllMocks();

    const module: TestingModule = await Test.createTestingModule({
      providers: [${name}Service, { provide: ${name}Repository, useValue: repo }],
    }).compile();

    service = module.get(${name}Service);
  });

  it('create delegates to the repository', async () => {
    repo.create.mockResolvedValue(sample);

    await expect(service.create(sample)).resolves.toEqual(sample);
    expect(repo.create).toHaveBeenCalledWith(sample);
  });

  it('findAll delegates to the repository', async () => {
    repo.findMany.mockResolvedValue([sample]);

    await expect(service.findAll()).resolves.toEqual([sample]);
    expect(repo.findMany).toHaveBeenCalledWith({});
  });

  it('findOne delegates to the repository', async () => {
    repo.findOne.mockResolvedValue(sample);

    await expect(service.findOne(keyQuery)).resolves.toEqual(sample);
    expect(repo.findOne).toHaveBeenCalledWith(keyQuery);
  });

  it('update delegates to the repository without upsert', async () => {
    repo.update.mockResolvedValue(sample);
    const payload = { ${updatableField.name}: ${newValue} };

    await expect(service.update({ query: keyQuery, payload })).resolves.toEqual(
      sample,
    );
    expect(repo.update).toHaveBeenCalledWith(keyQuery, payload, {
      upsert: false,
    });
  });

  it('remove delegates to the repository', async () => {
    repo.remove.mockResolvedValue(sample);

    await expect(service.remove(keyQuery)).resolves.toEqual(sample);
    expect(repo.remove).toHaveBeenCalledWith(keyQuery);
  });
});
`;
    fs.writeFileSync(path.join(dirPath, `${kebab(name)}.service.spec.ts`), content);
  }

  // ---- e2e spec ----
  {
    generateE2e(cfg);
  }

  // ---- bruno ----
  {
    generateBruno(cfg);
  }
}

function pascalCase(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// build a plain-JS sample value map for a field list
function buildSample(fields, seed = 1) {
  const sample = {};
  for (const f of fields) {
    sample[f.name] = sampleValueFor(f, seed);
  }
  return sample;
}

function sampleValueFor(f, seed) {
  if (f.kind === 'Embedded') {
    const obj = {};
    for (const sf of f.fields) obj[sf.name] = sampleValueFor(sf, seed);
    return obj;
  }
  if (f.kind === 'Int') return 100 + seed;
  if (f.kind === 'Float') return 12.5;
  if (f.kind === 'Boolean') return f.hasDefault ? f.default : true;
  if (f.kind === 'Date') return '__DATE__';
  if (f.email) return `user${seed}@example.com`;
  if (f.name === 'street') return '123 Main St';
  if (f.name === 'city') return 'Springfield';
  if (f.name === 'country') return 'Wonderland';
  if (f.name === 'zipCode') return '12345';
  return `${f.name}-${seed}`;
}

function renderJsValue(v) {
  if (v === '__DATE__') return `new Date('2024-01-01T00:00:00.000Z')`;
  if (typeof v === 'object' && v !== null) {
    const entries = Object.entries(v).map(([k, val]) => `${k}: ${renderJsValue(val)}`);
    return `{ ${entries.join(', ')} }`;
  }
  return JSON.stringify(v);
}

function renderSampleObject(sample, fields) {
  const lines = fields.map((f) => `    ${f.name}: ${renderJsValue(sample[f.name])},`);
  return `{\n${lines.join('\n')}\n  }`;
}

// GraphQL variable literal renderer (for e2e / bruno) — dates as ISO strings
function renderGqlValue(v) {
  if (v === '__DATE__') return `'2024-01-01T00:00:00.000Z'`;
  if (typeof v === 'object' && v !== null) {
    const entries = Object.entries(v).map(([k, val]) => `${k}: ${renderGqlValue(val)}`);
    return `{ ${entries.join(', ')} }`;
  }
  return JSON.stringify(v);
}

function renderJsonValue(v, indent = '') {
  if (v === '__DATE__') return `"2024-01-01T00:00:00.000Z"`;
  if (typeof v === 'object' && v !== null) {
    const inner = indent + '  ';
    const entries = Object.entries(v).map(([k, val]) => `${inner}"${k}": ${renderJsonValue(val, inner)}`);
    return `{\n${entries.join(',\n')}\n${indent}}`;
  }
  return JSON.stringify(v);
}

function generateE2e(cfg) {
  const { name, plural, dir, fields } = cfg;
  const camel = pascalToCamel(name);
  const sample = buildSample(fields, 1);
  const uniqueFields = fields.filter((f) => f.unique);
  const keyField = uniqueFields[0];
  const updatableField =
    fields.find((f) => !f.unique && f.kind === 'String') || fields.find((f) => !f.unique && f.kind !== 'Embedded');
  const newValue = updatableField.kind === 'String' ? `'${sample[updatableField.name]}-updated'` : JSON.stringify(sample[updatableField.name] + 1);

  const selectFields = fields.map((f) => (f.kind === 'Embedded' ? `${f.name} { ${f.fields.map((sf) => sf.name).join(' ')} }` : f.name)).join(' ');
  const keySelect = keyField.name;

  const content = `import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { App } from 'supertest/types';
import { Connection } from 'mongoose';
import { getConnectionToken } from '@nestjs/mongoose';
import { AppModule } from './../src/app.module';

interface GqlResponse {
  data?: Record<string, any>;
  errors?: Array<{ message: string }>;
}

// Requires MongoDB running (docker compose up -d mongodb) — AppModule boots
// the real database connection.
describe('${pascalCase(plural)} (e2e)', () => {
  let app: INestApplication<App>;
  let connection: Connection;

  const create${name} = ${renderJsE2eObject(sample, fields)};

  const gql = async (
    query: string,
    variables?: Record<string, unknown>,
  ): Promise<GqlResponse> => {
    const res = await request(app.getHttpServer())
      .post('/graphql')
      .send({ query, variables })
      .expect(200);
    return res.body as GqlResponse;
  };

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    // Mirror the global pipe from main.ts — whitelist behavior is part of the
    // contract under test.
    app.useGlobalPipes(
      new ValidationPipe({ whitelist: true, transform: true }),
    );
    await app.init();

    connection = app.get<Connection>(getConnectionToken());
    await connection.collection('${plural}').deleteMany({});
  });

  afterAll(async () => {
    await connection.collection('${plural}').deleteMany({});
    await app.close();
  });

  it('create${name} persists and returns the ${camel}', async () => {
    const body = await gql(
      \`mutation($input: Create${name}Input!) {
        create${name}(create${name}: $input) { ${selectFields} }
      }\`,
      { input: create${name} },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.create${name}).toEqual(create${name});
  });

  it('${plural} lists the created ${camel}', async () => {
    const body = await gql(\`{ ${plural} { ${keySelect} } }\`);

    expect(body.errors).toBeUndefined();
    expect(body.data?.${plural}).toEqual([{ ${keySelect}: create${name}.${keySelect} }]);
  });

  it('${camel} finds by ${keySelect}', async () => {
    const body = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.${camel}).toEqual({
      ${keySelect}: create${name}.${keySelect},
    });
  });

  it('update${name} applies and persists the change', async () => {
    const newValue = ${newValue};

    const updated = await gql(
      \`mutation($args: Update${name}Args!) {
        update${name}(update${name}Args: $args) { ${keySelect} ${updatableField.name} }
      }\`,
      {
        args: {
          query: { ${keySelect}: create${name}.${keySelect} },
          payload: { ${updatableField.name}: newValue },
        },
      },
    );

    expect(updated.errors).toBeUndefined();
    expect(updated.data?.update${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
      ${updatableField.name}: newValue,
    });

    const persisted = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${updatableField.name} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(persisted.data?.${camel}).toEqual({ ${updatableField.name}: newValue });
  });

  it('remove${name} deletes the ${camel}', async () => {
    const removed = await gql(
      \`mutation($get: Get${name}Input!) {
        remove${name}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(removed.errors).toBeUndefined();
    expect(removed.data?.remove${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
    });

    const list = await gql(\`{ ${plural} { ${keySelect} } }\`);
    expect(list.data?.${plural}).toEqual([]);
  });
});
`;
  fs.writeFileSync(path.join(ROOT, 'test', `${dir}.e2e-spec.ts`), content);
}

function renderJsE2eObject(sample, fields) {
  const lines = fields.map((f) => `    ${f.name}: ${renderJsValue(sample[f.name])},`);
  return `{\n${lines.join('\n')}\n  }`;
}

function generateBruno(cfg) {
  const { name, plural, dir, fields } = cfg;
  const camel = pascalToCamel(name);
  const sample = buildSample(fields, 1);
  const uniqueFields = fields.filter((f) => f.unique);
  const keyField = uniqueFields[0];
  const selectFields = fields.map((f) => (f.kind === 'Embedded' ? `${f.name} { ${f.fields.map((sf) => sf.name).join(' ')} }` : f.name)).join('\n      ');

  const brunoDir = path.join(ROOT, 'bruno', dir);
  fs.mkdirSync(brunoDir, { recursive: true });

  const header = (n) => `post {
  url: {{baseUrl}}/graphql
  body: graphql
  auth: none
}`;

