function pascalCase(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// build a plain-JS sample value map for a field list
function buildSample(fields, seed = 1) {
  const sample = {};
  for (const f of fields) {
    sample[f.name] = sampleValueFor(f, seed);
  }
  return sample;
}

function sampleValueFor(f, seed) {
  if (f.kind === 'Embedded') {
    const obj = {};
    for (const sf of f.fields) obj[sf.name] = sampleValueFor(sf, seed);
    return obj;
  }
  if (f.kind === 'Int') return 100 + seed;
  if (f.kind === 'Float') return 12.5;
  if (f.kind === 'Boolean') return f.hasDefault ? f.default : true;
  if (f.kind === 'Date') return '__DATE__';
  if (f.email) return `user${seed}@example.com`;
  if (f.name === 'street') return '123 Main St';
  if (f.name === 'city') return 'Springfield';
  if (f.name === 'country') return 'Wonderland';
  if (f.name === 'zipCode') return '12345';
  return `${f.name}-${seed}`;
}

function renderJsValue(v) {
  if (v === '__DATE__') return `new Date('2024-01-01T00:00:00.000Z')`;
  if (typeof v === 'object' && v !== null) {
    const entries = Object.entries(v).map(([k, val]) => `${k}: ${renderJsValue(val)}`);
    return `{ ${entries.join(', ')} }`;
  }
  return JSON.stringify(v);
}

function renderSampleObject(sample, fields) {
  const lines = fields.map((f) => `    ${f.name}: ${renderJsValue(sample[f.name])},`);
  return `{\n${lines.join('\n')}\n  }`;
}

// GraphQL variable literal renderer (for e2e / bruno) — dates as ISO strings
function renderGqlValue(v) {
  if (v === '__DATE__') return `'2024-01-01T00:00:00.000Z'`;
  if (typeof v === 'object' && v !== null) {
    const entries = Object.entries(v).map(([k, val]) => `${k}: ${renderGqlValue(val)}`);
    return `{ ${entries.join(', ')} }`;
  }
  return JSON.stringify(v);
}

function renderJsonValue(v, indent = '') {
  if (v === '__DATE__') return `"2024-01-01T00:00:00.000Z"`;
  if (typeof v === 'object' && v !== null) {
    const inner = indent + '  ';
    const entries = Object.entries(v).map(([k, val]) => `${inner}"${k}": ${renderJsonValue(val, inner)}`);
    return `{\n${entries.join(',\n')}\n${indent}}`;
  }
  return JSON.stringify(v);
}

function generateE2e(cfg) {
  const { name, plural, dir, fields } = cfg;
  const camel = pascalToCamel(name);
  const sample = buildSample(fields, 1);
  const uniqueFields = fields.filter((f) => f.unique);
  const keyField = uniqueFields[0];
  const updatableField =
    fields.find((f) => !f.unique && f.kind === 'String') || fields.find((f) => !f.unique && f.kind !== 'Embedded');
  const newValue = renderUpdatedJsValue(updatableField, sample[updatableField.name]);

  const selectFields = fields.map((f) => (f.kind === 'Embedded' ? `${f.name} { ${f.fields.map((sf) => sf.name).join(' ')} }` : f.name)).join(' ');
  const keySelect = keyField.name;

  const content = `import { Test, TestingModule } from '@nestjs/testing';
