'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = '/workspace';

// ---------- field helpers ----------

function scalarField(name, kind, opts = {}) {
  return {
    name,
    kind, // String | Int | Float | Boolean | Date
    required: opts.required !== false,
    unique: !!opts.unique,
    hasDefault: Object.prototype.hasOwnProperty.call(opts, 'default'),
    default: opts.default,
    optional: !!opts.optional,
    email: !!opts.email,
  };
}

function embeddedField(name, typeName, fields) {
  return {
    name,
    kind: 'Embedded',
    typeName,
    required: true,
    unique: false,
    hasDefault: false,
    optional: false,
    fields,
  };
}

const createOptional = (f) => f.hasDefault || f.optional;
const entityNullable = (f) => f.optional;

const gqlTypeExpr = (f) => {
  if (f.kind === 'Embedded') return f.typeName;
  if (f.kind === 'Int') return 'Int';
  if (f.kind === 'Float') return 'Float';
  if (f.kind === 'Date') return 'Date';
  if (f.kind === 'Boolean') return 'Boolean';
  return 'String';
};

const inputTypeExpr = (f) => (f.kind === 'Embedded' ? `${f.typeName}Input` : gqlTypeExpr(f));

const tsTypeExpr = (f) => {
  if (f.kind === 'Embedded') return f.typeName;
  if (f.kind === 'Int' || f.kind === 'Float') return 'number';
  if (f.kind === 'Date') return 'Date';
  if (f.kind === 'Boolean') return 'boolean';
  return 'string';
};

const inputTsTypeExpr = (f) => (f.kind === 'Embedded' ? `${f.typeName}Input` : tsTypeExpr(f));

const validatorDecorator = (f) => {
  if (f.kind === 'Embedded') return null; // uses ValidateNested
  if (f.kind === 'Int') return 'IsInt';
  if (f.kind === 'Float') return 'IsNumber';
  if (f.kind === 'Date') return 'IsDate';
  if (f.kind === 'Boolean') return 'IsBoolean';
  return f.email ? 'IsEmail' : 'IsString';
};

// ---------- code renderers ----------

function renderImports(imports) {
  // imports: array of {from, names: []}
  return imports
    .filter((i) => i.names.length > 0)
    .map((i) => `import { ${[...new Set(i.names)].sort().join(', ')} } from '${i.from}';`)
    .join('\n');
}

function renderFieldBlockEntity(f) {
  const gqlType = gqlTypeExpr(f);
  const nullable = entityNullable(f);
  const opts = nullable ? `, { nullable: true }` : '';
  const bang = nullable ? '?' : '!';
  const lines = [`  @Field(() => ${gqlType}${opts})`];
  if (f.kind === 'Embedded') {
    lines.push(`  @ValidateNested()`, `  @Type(() => ${f.typeName})`);
  } else {
    if (nullable) lines.push('  @IsOptional()');
    lines.push(`  @${validatorDecorator(f)}()`);
  }
  lines.push(`  ${f.name}${bang}: ${tsTypeExpr(f)};`);
  return lines.join('\n');
}

function renderFieldBlockCreate(f) {
  const gqlType = inputTypeExpr(f);
  const nullable = createOptional(f);
  const opts = nullable ? `, { nullable: true }` : '';
  const bang = nullable ? '?' : '!';
  const lines = [`  @Field(() => ${gqlType}${opts})`];
  if (f.kind === 'Embedded') {
    if (nullable) lines.push('  @IsOptional()');
    lines.push(`  @ValidateNested()`, `  @Type(() => ${f.typeName}Input)`);
  } else {
    if (nullable) lines.push('  @IsOptional()');
    lines.push(`  @${validatorDecorator(f)}()`);
  }
  lines.push(`  ${f.name}${bang}: ${inputTsTypeExpr(f)};`);
  return lines.join('\n');
}

function renderFieldBlockUpdate(f) {
  // all fields optional
  const gqlType = inputTypeExpr(f);
  const lines = [`  @Field(() => ${gqlType}, { nullable: true })`, '  @IsOptional()'];
  if (f.kind === 'Embedded') {
    lines.push(`  @ValidateNested()`, `  @Type(() => ${f.typeName}Input)`);
  } else {
    lines.push(`  @${validatorDecorator(f)}()`);
  }
  lines.push(`  ${f.name}?: ${inputTsTypeExpr(f)};`);
  return lines.join('\n');
}

function renderFieldBlockGet(f) {
  const gqlType = gqlTypeExpr(f);
  const lines = [
    `  @Field(() => ${gqlType}, { nullable: true })`,
    '  @IsOptional()',
    `  @${validatorDecorator(f)}()`,
    `  ${f.name}?: ${tsTypeExpr(f)};`,
  ];
  return lines.join('\n');
}

function collectValidatorNames(fields, mode) {
  const names = new Set();
  let needsType = false;
  for (const f of fields) {
    if (f.kind === 'Embedded') {
      needsType = true;
      names.add('ValidateNested');
      if (mode === 'create' && createOptional(f)) names.add('IsOptional');
      if (mode === 'update') names.add('IsOptional');
      continue;
    }
    const v = validatorDecorator(f);
    names.add(v);
    if (mode === 'entity' && entityNullable(f)) names.add('IsOptional');
    if (mode === 'create' && createOptional(f)) names.add('IsOptional');
    if (mode === 'update') names.add('IsOptional');
    if (mode === 'get') names.add('IsOptional');
  }
  return { names: [...names], needsType };
}

function collectGqlNames(fields) {
  const names = new Set();
  for (const f of fields) {
    const t = gqlTypeExpr(f);
    if (t === 'Int' || t === 'Float') names.add(t);
  }
  return [...names];
}

// ---------- embedded type files ----------

function embeddedTypeName(typeName) {
  return typeName;
}

function renderEmbeddedEntity(dirPath, embedded) {
  const gqlExtra = collectGqlNames(embedded.fields);
  const { names: validatorNames } = collectValidatorNames(embedded.fields, 'entity');
  const body = embedded.fields.map(renderFieldBlockEntity).join('\n\n');
  const content = `${renderImports([
    { from: '@nestjs/graphql', names: ['Field', 'ObjectType', ...gqlExtra] },
    { from: 'class-validator', names: validatorNames },
  ])}

@ObjectType()
export class ${embedded.typeName} {
${body}
}
`;
  fs.writeFileSync(path.join(dirPath, 'entities', `${kebab(embedded.typeName)}.entity.ts`), content);
}

function renderEmbeddedInput(dirPath, embedded) {
  const gqlExtra = collectGqlNames(embedded.fields);
  const { names: validatorNames } = collectValidatorNames(embedded.fields, 'entity');
  const body = embedded.fields.map(renderFieldBlockEntity).join('\n\n');
  // input uses same required-ness as entity (embedded sub-fields all required per spec)
  const content = `${renderImports([
    { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
    { from: 'class-validator', names: validatorNames },
  ])}

@InputType()
export class ${embedded.typeName}Input {
${body}
}
`;
  fs.writeFileSync(path.join(dirPath, 'dto', `${kebab(embedded.typeName)}.input.dto.ts`), content);
}

// ---------- utils ----------

function kebab(str) {
  return str
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .toLowerCase();
}

function pascalToCamel(str) {
  return str.charAt(0).toLowerCase() + str.slice(1);
}

// ---------- main per-entity generation ----------

function generateEntity(cfg) {
  const { name, plural, dir, fields } = cfg;
  const camel = pascalToCamel(name);
  const dirPath = path.join(ROOT, 'src', dir);
  const testDirs = ['dto', 'entities', 'schemas'].map((d) => path.join(dirPath, d));
  for (const d of [dirPath, ...testDirs]) fs.mkdirSync(d, { recursive: true });

  const embeddedFields = fields.filter((f) => f.kind === 'Embedded');
  for (const ef of embeddedFields) {
    renderEmbeddedEntity(dirPath, ef);
    renderEmbeddedInput(dirPath, ef);
  }

  const uniqueFields = fields.filter((f) => f.unique);

  // ---- entity.ts ----
  {
    const gqlExtra = collectGqlNames(fields);
    const { names: validatorNames, needsType } = collectValidatorNames(fields, 'entity');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'ObjectType', ...gqlExtra] },
    ];
    if (needsType) imports.push({ from: 'class-transformer', names: ['Type'] });
    imports.push({ from: 'class-validator', names: validatorNames });
    for (const ef of embeddedFields) {
      imports.push({ from: `./${kebab(ef.typeName)}.entity`, names: [ef.typeName] });
    }
    const body = fields.map(renderFieldBlockEntity).join('\n\n');
    const content = `${renderImports(imports)}

@ObjectType()
export class ${name} {
${body}
}
`;
    fs.writeFileSync(path.join(dirPath, 'entities', `${kebab(name)}.entity.ts`), content);
  }

  // ---- dto/create-<x>.input.dto.ts ----
  {
    const gqlExtra = collectGqlNames(fields);
    const { names: validatorNames, needsType } = collectValidatorNames(fields, 'create');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
    ];
    if (needsType) imports.push({ from: 'class-transformer', names: ['Type'] });
    imports.push({ from: 'class-validator', names: validatorNames });
    for (const ef of embeddedFields) {
      imports.push({ from: `../dto/${kebab(ef.typeName)}.input.dto`, names: [`${ef.typeName}Input`] });
    }
    const body = fields.map(renderFieldBlockCreate).join('\n\n');
    const content = `${renderImports(imports)}

@InputType()
export class Create${name}Input {
${body}
}
`;
    fs.writeFileSync(path.join(dirPath, 'dto', `create-${kebab(name)}.input.dto.ts`), content);
  }

  // ---- dto/get-<x>.input.dto.ts ----
  {
    const gqlExtra = collectGqlNames(uniqueFields);
    const { names: validatorNames } = collectValidatorNames(uniqueFields, 'get');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
      { from: 'class-validator', names: validatorNames },
    ];
    const body = uniqueFields.map(renderFieldBlockGet).join('\n\n');
    const content = `${renderImports(imports)}

@InputType()
export class Get${name}Input {
${body}
}
`;
    fs.writeFileSync(path.join(dirPath, 'dto', `get-${kebab(name)}.input.dto.ts`), content);
  }

  // ---- dto/update-<x>.input.dto.ts ----
  {
    const gqlExtra = collectGqlNames(fields);
    const { names: validatorNames } = collectValidatorNames(fields, 'update');
    const imports = [
      { from: '@nestjs/graphql', names: ['Field', 'InputType', ...gqlExtra] },
      { from: 'class-transformer', names: ['Type'] },
      { from: 'class-validator', names: [...new Set([...validatorNames, 'ValidateNested'])] },
      { from: `./get-${kebab(name)}.input.dto`, names: [`Get${name}Input`] },
    ];
    for (const ef of embeddedFields) {
      imports.push({ from: `../dto/${kebab(ef.typeName)}.input.dto`, names: [`${ef.typeName}Input`] });
    }
    const body = fields.map(renderFieldBlockUpdate).join('\n\n');
    const content = `${renderImports(imports)}

@InputType()
export class Update${name}Payload {
${body}
}

@InputType()
export class Update${name}Args {
  @Field(() => Get${name}Input)
  @ValidateNested()
  @Type(() => Get${name}Input)
  query!: Get${name}Input;

  @Field(() => Update${name}Payload)
  @ValidateNested()
  @Type(() => Update${name}Payload)
  payload!: Update${name}Payload;
}
`;
    fs.writeFileSync(path.join(dirPath, 'dto', `update-${kebab(name)}.input.dto.ts`), content);
  }

  // ---- schemas/<x>.schema.ts ----
  {
    const schemaFieldLine = (f, indent = '  ') => {
      if (f.kind === 'Embedded') {
        return `${indent}${f.name}: { type: ${f.typeName}Schema, required: true },`;
      }
      const mongoType =
        f.kind === 'Int' || f.kind === 'Float'
          ? 'Number'
          : f.kind === 'Date'
            ? 'Date'
            : f.kind === 'Boolean'
