      }\`,
      {
        args: {
          query: { ${keySelect}: create${name}.${keySelect} },
          payload: { ${updatableField.name}: newValue },
        },
      },
    );

    expect(updated.errors).toBeUndefined();
    expect(updated.data?.update${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
      ${updatableField.name}: newValue,
    });

    const persisted = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${updatableField.name} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(persisted.data?.${camel}).toEqual({ ${updatableField.name}: newValue });
  });

  it('remove${name} deletes the ${camel}', async () => {
    const removed = await gql(
      \`mutation($get: Get${name}Input!) {
        remove${name}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(removed.errors).toBeUndefined();
    expect(removed.data?.remove${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
    });

    const list = await gql(\`{ ${plural} { ${keySelect} } }\`);
    expect(list.data?.${plural}).toEqual([]);
  });
});
`;
  fs.writeFileSync(path.join(ROOT, 'test', `${dir}.e2e-spec.ts`), content);
}

// produces a JS-literal string for a *changed* value, used in update tests
function renderUpdatedJsValue(field, originalValue) {
  if (field.kind === 'String') return `'${originalValue}-updated'`;
  if (field.kind === 'Int' || field.kind === 'Float') return JSON.stringify(originalValue + 1);
  if (field.kind === 'Boolean') return JSON.stringify(!originalValue);
  if (field.kind === 'Date') return `new Date('2025-06-15T00:00:00.000Z')`;
  return JSON.stringify(originalValue);
}

// produces the *changed* value as a plain JS value (not a source-code string), for JSON contexts
function updatedPlainValue(field, originalValue) {
  if (field.kind === 'String') return `${originalValue}-updated`;
  if (field.kind === 'Int' || field.kind === 'Float') return originalValue + 1;
  if (field.kind === 'Boolean') return !originalValue;
  if (field.kind === 'Date') return '2025-06-15T00:00:00.000Z';
  return originalValue;
}

function renderJsE2eObject(sample, fields) {
  const lines = fields.map((f) => `    ${f.name}: ${renderJsValue(sample[f.name])},`);
  return `{\n${lines.join('\n')}\n  }`;
}

function generateBruno(cfg) {
