import { getConnectionToken } from '@nestjs/mongoose';
import { AppModule } from './../src/app.module';

interface GqlResponse {
  data?: Record<string, any>;
  errors?: Array<{ message: string }>;
}

// Requires MongoDB running (docker compose up -d mongodb) — AppModule boots
// the real database connection.
describe('${pascalCase(plural)} (e2e)', () => {
  let app: INestApplication<App>;
  let connection: Connection;

  const create${name} = ${renderJsE2eObject(sample, fields)};

  const gql = async (
    query: string,
    variables?: Record<string, unknown>,
  ): Promise<GqlResponse> => {
    const res = await request(app.getHttpServer())
      .post('/graphql')
      .send({ query, variables })
      .expect(200);
    return res.body as GqlResponse;
  };

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    // Mirror the global pipe from main.ts — whitelist behavior is part of the
    // contract under test.
    app.useGlobalPipes(
      new ValidationPipe({ whitelist: true, transform: true }),
    );
    await app.init();

    connection = app.get<Connection>(getConnectionToken());
    await connection.collection('${plural}').deleteMany({});
  });

  afterAll(async () => {
    await connection.collection('${plural}').deleteMany({});
    await app.close();
  });

  it('create${name} persists and returns the ${camel}', async () => {
    const body = await gql(
      \`mutation($input: Create${name}Input!) {
        create${name}(create${name}: $input) { ${selectFields} }
      }\`,
      { input: create${name} },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.create${name}).toEqual(create${name});
  });

  it('${plural} lists the created ${camel}', async () => {
    const body = await gql(\`{ ${plural} { ${keySelect} } }\`);

    expect(body.errors).toBeUndefined();
    expect(body.data?.${plural}).toEqual([{ ${keySelect}: create${name}.${keySelect} }]);
  });

  it('${camel} finds by ${keySelect}', async () => {
    const body = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.${camel}).toEqual({
      ${keySelect}: create${name}.${keySelect},
    });
  });

  it('update${name} applies and persists the change', async () => {
    const newValue = ${newValue};

    const updated = await gql(
      \`mutation($args: Update${name}Args!) {
        update${name}(update${name}Args: $args) { ${keySelect} ${updatableField.name} }
      }\`,
      {
        args: {
          query: { ${keySelect}: create${name}.${keySelect} },
          payload: { ${updatableField.name}: newValue },
        },
      },
    );

    expect(updated.errors).toBeUndefined();
    expect(updated.data?.update${name}).toEqual({
      ${keySelect}: create${name}.${keySelect},
      ${updatableField.name}: newValue,
    });

    const persisted = await gql(
      \`query($get: Get${name}Input!) {
        ${camel}(get${name}: $get) { ${updatableField.name} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
    );

    expect(persisted.data?.${camel}).toEqual({ ${updatableField.name}: newValue });
  });

  it('remove${name} deletes the ${camel}', async () => {
    const removed = await gql(
      \`mutation($get: Get${name}Input!) {
        remove${name}(get${name}: $get) { ${keySelect} }
      }\`,
      { get: { ${keySelect}: create${name}.${keySelect} } },
