import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { App } from 'supertest/types';
import { Connection } from 'mongoose';
import { getConnectionToken } from '@nestjs/mongoose';
import { AppModule } from './../src/app.module';

interface GqlResponse {
  data?: Record<string, any>;
  errors?: Array<{ message: string }>;
}

// Requires MongoDB running (docker compose up -d mongodb) — AppModule boots
// the real database connection.
describe('Warehouses (e2e)', () => {
  let app: INestApplication<App>;
  let connection: Connection;

  const createWarehouse = {
    code: "code-1",
    name: "name-1",
    capacity: 101,
    location: { street: "123 Main St", city: "Springfield", latitude: 12.5, longitude: 12.5 },
  };

  const gql = async (
    query: string,
    variables?: Record<string, unknown>,
  ): Promise<GqlResponse> => {
    const res = await request(app.getHttpServer())
      .post('/graphql')
      .send({ query, variables })
      .expect(200);
    return res.body as GqlResponse;
  };

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    // Mirror the global pipe from main.ts — whitelist behavior is part of the
    // contract under test.
    app.useGlobalPipes(
      new ValidationPipe({ whitelist: true, transform: true }),
    );
    await app.init();

    connection = app.get<Connection>(getConnectionToken());
    await connection.collection('warehouses').deleteMany({});
  });

  afterAll(async () => {
    await connection.collection('warehouses').deleteMany({});
    await app.close();
  });

  it('createWarehouse persists and returns the warehouse', async () => {
    const body = await gql(
      `mutation($input: CreateWarehouseInput!) {
        createWarehouse(createWarehouse: $input) { code name capacity location { street city latitude longitude } }
      }`,
      { input: createWarehouse },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.createWarehouse).toEqual(createWarehouse);
  });

  it('warehouses lists the created warehouse', async () => {
    const body = await gql(`{ warehouses { code } }`);

    expect(body.errors).toBeUndefined();
    expect(body.data?.warehouses).toEqual([{ code: createWarehouse.code }]);
  });

  it('warehouse finds by code', async () => {
    const body = await gql(
      `query($get: GetWarehouseInput!) {
        warehouse(getWarehouse: $get) { code }
      }`,
      { get: { code: createWarehouse.code } },
    );

    expect(body.errors).toBeUndefined();
    expect(body.data?.warehouse).toEqual({
      code: createWarehouse.code,
    });
  });

  it('updateWarehouse applies and persists the change', async () => {
    const newValue = 'name-1-updated';

    const updated = await gql(
      `mutation($args: UpdateWarehouseArgs!) {
        updateWarehouse(updateWarehouseArgs: $args) { code name }
      }`,
      {
        args: {
          query: { code: createWarehouse.code },
          payload: { name: newValue },
        },
      },
    );

    expect(updated.errors).toBeUndefined();
    expect(updated.data?.updateWarehouse).toEqual({
      code: createWarehouse.code,
      name: newValue,
    });

    const persisted = await gql(
      `query($get: GetWarehouseInput!) {
        warehouse(getWarehouse: $get) { name }
      }`,
      { get: { code: createWarehouse.code } },
    );

    expect(persisted.data?.warehouse).toEqual({ name: newValue });
  });

  it('removeWarehouse deletes the warehouse', async () => {
    const removed = await gql(
      `mutation($get: GetWarehouseInput!) {
        removeWarehouse(getWarehouse: $get) { code }
      }`,
      { get: { code: createWarehouse.code } },
    );

    expect(removed.errors).toBeUndefined();
    expect(removed.data?.removeWarehouse).toEqual({
      code: createWarehouse.code,
    });

    const list = await gql(`{ warehouses { code } }`);
    expect(list.data?.warehouses).toEqual([]);
  });
});

